if ($json.error || status === 429 || status >= 500) return {json: {pause:true,reason:$json.error?'transport':'http_'+status}};
if (status !== 200) throw new Error('Unexpected service HTTP status: ' + status);
const verdict = $json.body?.verdict;
if (!['accepted','wrong_answer','runtime_error','time_limit','output_limit','memory_limit'].includes(verdict))
  throw new Error('Invalid sandbox verdict');
if(verdict!=='accepted'){data.reviewReason='independent_witness_disagrees';return {json:{phase:'needs_review',data}};}data.variant=0;data.survivors=[];data.faultsKilled=0;return {json:{phase:'mutate',data}};

const {phase,data} = $("Phase: plausible").item.json;
const status = $json.statusCode;
if ($json.error || status === 429 || status >= 500) return {json: {pause:true,reason:$json.error?'transport':'http_'+status}};
if (status !== 200) throw new Error('Unexpected service HTTP status: ' + status);
const verdict = $json.body?.verdict;
if (!['accepted','wrong_answer','runtime_error','time_limit','output_limit','memory_limit'].includes(verdict))
  throw new Error('Invalid sandbox verdict');
if(verdict==='accepted'){data.variant++;data.probeCase=0;data.faultsKilled=data.variant;return {json:{phase:data.variant<data.faults.length?'mutate':'certified',data}};}
if(verdict!=='wrong_answer'||++data.probeCase>=data.examples.length+data.cases.length){data.reviewReason='probe_not_plausible';return {json:{phase:'needs_review',data}};}return {json:{phase:'plausible',data}};
